pub fn dump_Mvar(out: &mut impl Write, path: &str, value: &Mvar<'_>) -> io::Result<()> {
    let dump_args = crate::dump_support::arguments();
    if !crate::dump_support::visit(out, path, 1892120077, value.offset_data().len(), dump_args)? {
        return Ok(());
    }
    let base = value.offset_data();
    {
        let path = &format!("{path}.version");
        let fieldValue = value.version();
        writeln!(out, "{path}.major={}", fieldValue.major)?;
        writeln!(out, "{path}.minor={}", fieldValue.minor)?;
    }
    {
        let path = &format!("{path}.reserved");
        let fieldValue = base
            .read_at::<u16>(value._reserved_byte_range().start)
            .unwrap_or_default();
        writeln!(out, "{path}={}", fieldValue)?;
    }
    {
        let path = &format!("{path}.valueRecordSize");
        let fieldValue = value.value_record_size();
        writeln!(out, "{path}={}", fieldValue)?;
    }
    {
        let path = &format!("{path}.valueRecordCount");
        let fieldValue = value.value_record_count();
        writeln!(out, "{path}={}", fieldValue)?;
    }
    {
        let path = &format!("{path}.itemVariationStoreOffset");
        let fieldValue = value.item_variation_store_offset();
        let rawOffset = fieldValue.offset();
        writeln!(out, "{path}={}", rawOffset.to_u32())?;
    }
    {
        let path = &format!("{path}.itemVariationStore");
        let target_args: [u64; 3] = [0, 0, 0];
        crate::dump_support::set_arguments(target_args);
        match value.item_variation_store() {
            None => writeln!(out, "{path}=none")?,
            Some(resolved) => match resolved {
                Ok(table) => table.dump(out, path)?,
                Err(error) => writeln!(out, "{path}.error={}", crate::error(error))?,
            },
        }
    }
    {
        let path = &format!("{path}.valueRecords");
        let fieldValue = value.value_records();
        writeln!(out, "{path}.length={}", fieldValue.len())?;
        for (index, item) in fieldValue.iter().enumerate() {
            let path = &format!("{path}[{index}]");
            crate::dump_support::set_arguments([0; 3]);
            dump_ValueRecord(out, path, item, base)?;
        }
    }
    Ok(())
}

impl DumpTable for Mvar<'_> {
    fn dump(&self, out: &mut impl Write, path: &str) -> io::Result<()> {
        dump_Mvar(out, path, self)
    }
}

pub fn dump_ValueRecord(
    out: &mut impl Write,
    path: &str,
    value: &ValueRecord,
    base: FontData<'_>,
) -> io::Result<()> {
    let dump_args = crate::dump_support::arguments();
    if !crate::dump_support::enter(path) {
        return writeln!(out, "{path}=traversal-limit");
    }
    {
        let path = &format!("{path}.valueTag");
        let fieldValue = value.value_tag();
        writeln!(
            out,
            "{path}={}",
            u32::from_be_bytes(fieldValue.to_be_bytes())
        )?;
    }
    {
        let path = &format!("{path}.deltaSetOuterIndex");
        let fieldValue = value.delta_set_outer_index();
        writeln!(out, "{path}={}", fieldValue)?;
    }
    {
        let path = &format!("{path}.deltaSetInnerIndex");
        let fieldValue = value.delta_set_inner_index();
        writeln!(out, "{path}={}", fieldValue)?;
    }
    Ok(())
}

pub fn dump_tables(
    out: &mut impl Write,
    path: &str,
    font: &read_fonts::FontRef<'_>,
) -> io::Result<()> {
    use read_fonts::FontRead;
    {
        crate::dump_support::begin_table();
        let path = &format!("{path}.MVAR");
        let tag = Tag::new(b"MVAR");
        match font
            .table_data(tag)
            .ok_or(ReadError::TableIsMissing(tag))
            .and_then(Mvar::read)
        {
            Ok(table) => dump_Mvar(out, path, &table)?,
            Err(error) => writeln!(out, "{path}.error={}", crate::error(error))?,
        }
    }
    Ok(())
}
